package com.gameaggregator.authorizationservice.application; import static com.gameaggregator.authorizationservice.api.AuthorizationDtos.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; import com.gameaggregator.authorizationservice.infrastructure.*; import java.util.*; import org.junit.jupiter.api.Test; class AuthorizationServiceTest { @Test void deniesMissingPermission(){ TenantAccessClient client=mock(TenantAccessClient.class); AuthorizationAuditRepository audits=mock(AuthorizationAuditRepository.class); UUID user=UUID.randomUUID(),tenant=UUID.randomUUID(); when(client.access(tenant,"Bearer token")).thenReturn(new AccessContext(user,tenant,Set.of("MEMBER"),Set.of("game:read"))); AuthorizationDecision result=new AuthorizationService(client,audits).check(user,new AuthorizationRequest(tenant,"game:delete",tenant,"TENANT","SANDBOX","ACTIVE"),"Bearer token"); assertThat(result.allowed()).isFalse(); assertThat(result.reason()).isEqualTo("MISSING_PERMISSION"); verify(audits).save(any()); } }
